INSERT INTO `configuration` VALUES (1,'Store Name','STORE_NAME','Indianapolis EMS','The name of my store <br>(Indianapolis EMS is the default)',1,1,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(2,'Store Owner','STORE_OWNER','Indianapolis EMS Logistics','The name of my store owner',1,2,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(3,'Telephone - Customer Service','STORE_TELEPHONE_CUSTSERVICE','','Enter a telephone number for customers to reach your Customer Service department. This number may be sent as part of payment transaction details.',1,3,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(4,'Country','STORE_COUNTRY','223','The country my store is located in <br /><br /><strong>Note: Please remember to update the store zone.</strong>',1,6,NULL,'2022-12-23 15:50:16','zen_get_country_name','zen_cfg_pull_down_country_list(',NULL),(5,'Zone','STORE_ZONE','24','The zone my store is located in',1,7,NULL,'2022-12-23 15:50:16','zen_cfg_get_zone_name','zen_cfg_pull_down_zone_list(',NULL),(6,'Expected Sort Order','EXPECTED_PRODUCTS_SORT','desc','This is the sort order used in the expected products box.',1,8,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'asc\', \'desc\'), ',NULL),(7,'Expected Sort Field','EXPECTED_PRODUCTS_FIELD','date_expected','The column to sort by in the expected products box.',1,9,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'products_name\', \'date_expected\'), ',NULL),(8,'Switch To Default Language Currency','USE_DEFAULT_LANGUAGE_CURRENCY','false','Automatically switch to the language\'s currency when it is changed',1,10,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(9,'Language Selector','LANGUAGE_DEFAULT_SELECTOR','Default','Should the default language be based on the Store preferences, or the customer\'s browser settings?<br /><br />Default: Store\'s default settings',1,11,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'Default\', \'Browser\'), ',NULL),(10,'Use Search-Engine Safe URLs (still in development)','SEARCH_ENGINE_FRIENDLY_URLS','false','Use search-engine safe urls for all site links',6,12,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(11,'Display Cart After Adding Product','DISPLAY_CART','true','Display the shopping cart after adding a product (or return back to their origin)',1,14,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(12,'Default Search Operator','ADVANCED_SEARCH_DEFAULT_OPERATOR','and','Default search operators',1,17,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'and\', \'or\'), ',NULL),(13,'Include meta-tags in product search?','ADVANCED_SEARCH_INCLUDE_METATAGS','true','Should a product\'s meta-tag keywords and meta-tag descriptions be considered in any <code>advanced_search_results</code> displayed?',1,18,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'),',NULL),(14,'Store Address and Phone','STORE_NAME_ADDRESS','3930 Georgetown Road\r\nIndianapolis, Indiana\r\n46254\r\nUnited States of America','This is the Store Name, Address and Phone used on printable documents and displayed online',1,7,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_textarea(',NULL),(15,'Show Category Counts','SHOW_COUNTS','true','Count recursively how many products are in each category',1,19,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(16,'Tax Decimal Places','TAX_DECIMAL_PLACES','0','Pad the tax value this amount of decimal places',1,20,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(17,'Display Prices with Tax','DISPLAY_PRICE_WITH_TAX','false','Display prices with tax included (true) or add the tax at the end (false)',1,21,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(18,'Display Prices with Tax in Admin','DISPLAY_PRICE_WITH_TAX_ADMIN','false','Display prices with tax included (true) or add the tax at the end (false) in Admin(Invoices)',1,21,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(19,'Basis of Product Tax','STORE_PRODUCT_TAX_BASIS','Shipping','On what basis is Product Tax calculated. Options are<br />Shipping - Based on customers Shipping Address<br />Billing Based on customers Billing address<br />Store - Based on Store address if Billing/Shipping Zone equals Store zone',1,21,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'Shipping\', \'Billing\', \'Store\'), ',NULL),(20,'Basis of Shipping Tax','STORE_SHIPPING_TAX_BASIS','Shipping','On what basis is Shipping Tax calculated. Options are<br />Shipping - Based on customers Shipping Address<br />Billing Based on customers Billing address<br />Store - Based on Store address if Billing/Shipping Zone equals Store zone - Can be overridden by correctly written Shipping Module',1,21,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'Shipping\', \'Billing\', \'Store\'), ',NULL),(21,'Sales Tax Display Status','STORE_TAX_DISPLAY_STATUS','0','Always show Sales Tax even when amount is $0.00?<br />0= Off<br />1= On',1,21,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'0\', \'1\'), ',NULL),(22,'Show Split Tax Lines','SHOW_SPLIT_TAX_CHECKOUT','false','If multiple tax rates apply, show each rate as a separate line at checkout',1,22,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(23,'PA-DSS Admin Session Timeout Enforced?','PADSS_ADMIN_SESSION_TIMEOUT_ENFORCED','1','PA-DSS Compliance requires that any Admin login sessions expire after 15 minutes of inactivity. <strong>Disabling this makes your site NON-COMPLIANT with PA-DSS rules, thus invalidating any certification.</strong>',1,30,'2022-12-23 15:50:16','2022-12-23 15:50:16',NULL,'zen_cfg_select_drop_down(array(array(\'id\'=>\'0\', \'text\'=>\'Non-Compliant\'), array(\'id\'=>\'1\', \'text\'=>\'On\')),',NULL),(24,'PA-DSS Strong Password Rules Enforced?','PADSS_PWD_EXPIRY_ENFORCED','1','PA-DSS Compliance requires that admin passwords must be changed after 90 days and cannot re-use the last 4 passwords. <strong>Disabling this makes your site NON-COMPLIANT with PA-DSS rules, thus invalidating any certification.</strong>',1,30,'2022-12-23 15:50:16','2022-12-23 15:50:16',NULL,'zen_cfg_select_drop_down(array(array(\'id\'=>\'0\', \'text\'=>\'Non-Compliant\'), array(\'id\'=>\'1\', \'text\'=>\'On\')),',NULL),(25,'PA-DSS Ajax Checkout?','PADSS_AJAX_CHECKOUT','1','PA-DSS Compliance requires that for some inbuilt payment methods, that we use ajax to draw the checkout confirmation screen. While this will only happen if one of those payment methods is actually present, some people may want the traditional checkout flow <strong>Disabling this makes your site NON-COMPLIANT with PA-DSS rules, thus invalidating any certification.</strong>',1,30,'2022-12-23 15:50:16','2022-12-23 15:50:16',NULL,'zen_cfg_select_drop_down(array(array(\'id\'=>\'0\', \'text\'=>\'Non-Compliant\'), array(\'id\'=>\'1\', \'text\'=>\'On\')),',NULL),(26,'Customer <em>Place Order</em>: Single Admin ID','EMP_LOGIN_ADMIN_ID','0','Identify the ID number of an admin that is permitted to use the <em>Place Order</em> feature on the customers list, regardless of their assigned admin-profile. Set the value to 0 to disable the <em>Single Admin ID</em> feature.',1,300,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(27,'Customer <em>Place Order</em>: Passwordless Login','EMP_LOGIN_AUTOMATIC','true','Login directly to store without entering credentials',1,302,'2023-01-09 08:53:16','2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'),',NULL),(28,'Customer <em>Place Order</em>: Admin Profiles','EMP_LOGIN_ADMIN_PROFILE_ID','1','Identify the admin <em>User Profile IDs</em> that are permitted to use the <em>Place Order</em> feature on the customers list &mdash; all admins that are in these profiles are permitted. Enter the value as a comma-separated list (intervening blanks are OK) of Admin Profile IDs, e.g. <b>1, 2, 3</b>. Set the value to 0 to disable the <em>Admin Profiles</em> feature.<br><br><b>Default: 0 </b>',1,301,'2023-01-09 08:53:10','2022-12-23 15:50:16',NULL,NULL,NULL),(29,'Admin Session Time Out in Seconds','SESSION_TIMEOUT_ADMIN','900','Enter the time in seconds.<br />Max allowed is 900 for PCI Compliance Reasons.<br /> Default=900<br />Example: 900= 15 min <br /><br />Note: Too few seconds can result in timeout issues when adding/editing products',1,40,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(30,'Admin Set max_execution_time for processes','GLOBAL_SET_TIME_LIMIT','60','Enter the time in seconds for how long the max_execution_time of processes should be. Default=60<br />Example: 60= 1 minute<br /><br />Note: Changing the time limit is only needed if you are having problems with the execution time of a process',1,42,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(31,'Show if version update available','SHOW_VERSION_UPDATE_IN_HEADER','true','Automatically check to see if a new version of Zen Cart is available. Enabling this can sometimes slow down the loading of Admin pages. (Displayed on main Index page after login, and Server Info page.)',1,44,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(32,'Store Status','STORE_STATUS','0','What is your Store Status<br />0= Normal Store<br />1= Showcase no prices<br />2= Showcase with prices',1,25,'2023-01-09 08:53:37','2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'0\', \'1\', \'2\'), ',NULL),(33,'Server Uptime','DISPLAY_SERVER_UPTIME','true','Displaying Server uptime can cause entries in error logs on some servers. (true = Display, false = don\'t display)',1,46,'2003-11-08 20:24:47','0001-01-01 00:00:00','','zen_cfg_select_option(array(\'true\', \'false\'),',NULL),(34,'Missing Page Check','MISSING_PAGE_CHECK','Page Not Found','Zen Cart can check for missing pages in the URL and redirect to Index page. For debugging you may want to turn this off. <br /><br /><strong>Default=On</strong><br />On = Send missing pages to \'index\'<br />Off = Don\'t check for missing pages<br />Page Not Found = display the Page-Not-Found page',1,48,'2003-11-08 20:24:47','0001-01-01 00:00:00','','zen_cfg_select_option(array(\'On\', \'Off\', \'Page Not Found\'),',NULL),(35,'cURL Proxy Status','CURL_PROXY_REQUIRED','False','Does your host require that you use a proxy for cURL communication?',6,50,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'True\', \'False\'), ',NULL),(36,'cURL Proxy Address','CURL_PROXY_SERVER_DETAILS','','If you have a hosting service that requires use of a proxy to talk to external sites via cURL, enter their proxy address here.<br />format: address:port<br />ie: 127.0.0.1:3128',6,51,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(37,'HTML Editor','HTML_EDITOR_PREFERENCE','CKEDITOR','Please select the HTML/Rich-Text editor you wish to use for composing Admin-related emails, newsletters, and product descriptions',1,110,'2023-01-17 12:13:26','2022-12-23 15:50:16',NULL,'zen_cfg_pull_down_htmleditors(',NULL),(38,'Default for Notify Customer on Order Status Update?','NOTIFY_CUSTOMER_DEFAULT','1','Set the default email behavior on status update to Send Email, Do Not Send Email, or Hide Update.',1,120,'2022-12-23 15:50:16','2022-12-23 15:50:16',NULL,'zen_cfg_select_drop_down(array( array(\'id\'=>\'1\', \'text\'=>\'Email\'), array(\'id\'=>\'0\', \'text\'=>\'No Email\'), array(\'id\'=>\'-1\', \'text\'=>\'Hide\')),',NULL),(39,'Show Category Counts - Admin','SHOW_COUNTS_ADMIN','true','Show Category Counts in Admin?',1,19,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(40,'Show linked status for categories','SHOW_CATEGORY_PRODUCTS_LINKED_STATUS','true','Show Category products linked status?',1,19,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_select_option(array(\'true\', \'false\'), ',NULL),(41,'Currency Conversion Ratio','CURRENCY_UPLIFT_RATIO','1.05','When auto-updating currencies, what \"uplift\" ratio should be used to calculate the exchange rate used by your store?<br />ie: the bank rate is obtained from the currency-exchange servers; how much extra do you want to charge in order to make up the difference between the bank rate and the consumer rate?<br /><br /><strong>Default: 1.05 </strong><br />This will cause the published bank rate to be multiplied by 1.05 to set the currency rates in your store.',1,55,NULL,'2022-12-23 15:50:16',NULL,NULL,NULL),(42,'Currency Exchange Rate: Primary Source','CURRENCY_SERVER_PRIMARY','ecb','Where to request external currency updates from (Primary source)<br><br>Additional sources can be installed via plugins.',1,55,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_pull_down_exchange_rate_sources(',NULL),(43,'Currency Exchange Rate: Secondary Source','CURRENCY_SERVER_BACKUP','boc','Where to request external currency updates from (Secondary source)<br><br>Additional sources can be installed via plugins.',1,55,NULL,'2022-12-23 15:50:16',NULL,'zen_cfg_pull_down_exchange_rate_sources(',NULL),(44,'First Name','ENTRY_FIRST_NAME_MIN_LENGTH','2','Minimum length of first name',2,1,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_FIRST_NAME_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(45,'Last Name','ENTRY_LAST_NAME_MIN_LENGTH','2','Minimum length of last name',2,2,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_LAST_NAME_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(46,'Date of Birth','ENTRY_DOB_MIN_LENGTH','10','Minimum length of date of birth',2,3,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_DOB_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(47,'E-Mail Address','ENTRY_EMAIL_ADDRESS_MIN_LENGTH','6','Minimum length of e-mail address',2,4,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_EMAIL_ADDRESS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(48,'Street Address','ENTRY_STREET_ADDRESS_MIN_LENGTH','5','Minimum length of street address',2,5,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_STREET_ADDRESS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(49,'Company','ENTRY_COMPANY_MIN_LENGTH','0','Minimum length of company name',2,6,'2023-01-10 11:24:13','2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_COMPANY_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(50,'Post Code','ENTRY_POSTCODE_MIN_LENGTH','4','Minimum length of post code',2,7,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_POSTCODE_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(51,'City','ENTRY_CITY_MIN_LENGTH','2','Minimum length of city',2,8,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_CITY_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(52,'State','ENTRY_STATE_MIN_LENGTH','2','Minimum length of state',2,9,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_STATE_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(53,'Telephone Number','ENTRY_TELEPHONE_MIN_LENGTH','3','Minimum length of telephone number',2,10,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_TELEPHONE_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(54,'Password','ENTRY_PASSWORD_MIN_LENGTH','7','Minimum length of password',2,11,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_PASSWORD_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(55,'Credit Card Owner Name','CC_OWNER_MIN_LENGTH','3','Minimum length of credit card owner name',2,12,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_CC_OWNER_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(56,'Credit Card Number','CC_NUMBER_MIN_LENGTH','10','Minimum length of credit card number',2,13,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_CC_NUMBER_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(57,'Product Review Text','REVIEW_TEXT_MIN_LENGTH','50','Minimum length of product review text',2,14,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_REVIEW_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(58,'Best Sellers','MIN_DISPLAY_BESTSELLERS','1','Minimum number of best sellers to display',2,15,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_DISPLAY_BESTSELLERS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(59,'Also Purchased Products','MIN_DISPLAY_ALSO_PURCHASED','1','Minimum number of products to display in the \'Also Purchased\' box',2,16,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_DISPLAY_ALSO_PURCHASED_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(60,'Nick Name','ENTRY_NICK_MIN_LENGTH','3','Minimum length of Nick Name',2,1,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_ENTRY_NICK_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(61,'Admin Usernames','ADMIN_NAME_MINIMUM_LENGTH','6','Minimum length of admin usernames (must be 4 or more)',2,18,'2023-01-09 08:53:52','2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MIN_ADMIN_USER_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":4}}}'),(62,'Address Book Entries','MAX_ADDRESS_BOOK_ENTRIES','0','Maximum address book entries a customer is allowed to have',3,1,'2023-01-16 15:29:32','2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_ADDRESS_BOOK_ENTRIES_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(63,'Admin Search Results Per Page','MAX_DISPLAY_SEARCH_RESULTS','20','Number of products to list on an Admin search result page',3,2,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_SEARCH_RESULTS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(64,'Prev/Next Navigation Page Links (Desktop)','MAX_DISPLAY_PAGE_LINKS','5','Number of numbered pagination links to display.',3,3,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_PAGE_LINKS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(65,'Prev/Next Navigation Page Links (Mobile)','MAX_DISPLAY_PAGE_LINKS_MOBILE','3','Number of numbered pagination links to display on Mobile devices (assuming your template supports mobile-specific settings)',3,3,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_PAGE_LINKS_MOBILE_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(66,'Products on Special Page','MAX_DISPLAY_SPECIAL_PRODUCTS','9','Number of products to show per page on the Specials page',3,4,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_SPECIAL_PRODUCTS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(67,'New Products Centerbox','MAX_DISPLAY_NEW_PRODUCTS','9','Number of products to display in the New Products centerbox',3,5,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_NEW_PRODUCTS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(68,'Upcoming Products Centerbox','MAX_DISPLAY_UPCOMING_PRODUCTS','10','Number of products to display in the Upcoming Products centerbox',3,6,NULL,'2022-12-23 15:50:16',NULL,NULL,'{\"error\":\"TEXT_MAX_ADMIN_DISPLAY_UPCOMING_PRODUCTS_LENGTH\",\"id\":\"FILTER_VALIDATE_INT\",\"options\":{\"options\":{\"min_range\":0}}}'),(69,'Manufacturers List - 